/**
 * Invite credential registry.
 *
 * Two separate credentials per multiplayer room:
 *   - inviteCode : short 6-char human code (31-symbol alphabet, ~30 bits), rate-limited lookups
 *   - inviteToken: 128-bit CSPRNG token (base64url, 22 chars) used in shareable links
 * Resolving either one NEVER returns the other. Both expire after `config.invite.ttlMs`
 * (auto-rotated for live rooms), and can be revoked or regenerated by the room owner.
 * Lookups are O(1) map hits on exact-format strings; nothing is scanned or compared linearly.
 */
import crypto from 'crypto';
import { config } from '../config.js';

const CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
export const INVITE_CODE_RE = /^[A-Z0-9]{6}$/;
export const INVITE_TOKEN_RE = /^[A-Za-z0-9_-]{22}$/;

export function generateInviteCode() {
  let s = '';
  for (let i = 0; i < 6; i++) s += CODE_ALPHABET[crypto.randomInt(CODE_ALPHABET.length)];
  return s;
}

export function generateInviteToken() {
  return crypto.randomBytes(16).toString('base64url');
}

class InviteRegistry {
  constructor() {
    this.byCode = new Map();
    this.byToken = new Map();
  }

  _remove(room) {
    if (room.inviteCode && this.byCode.get(room.inviteCode) === room) this.byCode.delete(room.inviteCode);
    if (room.inviteToken && this.byToken.get(room.inviteToken) === room) this.byToken.delete(room.inviteToken);
  }

  /** Issue (or re-issue) fresh credentials. Old ones stop resolving immediately. */
  issue(room, { code = null } = {}) {
    this._remove(room);
    if (room.maxPlayers <= 1) {
      room.inviteCode = null;
      room.inviteToken = null;
      return room;
    }
    let c = code && INVITE_CODE_RE.test(code) && !this.byCode.has(code) ? code : generateInviteCode();
    while (this.byCode.has(c)) c = generateInviteCode();
    let t = generateInviteToken();
    while (this.byToken.has(t)) t = generateInviteToken();
    room.inviteCode = c;
    room.inviteToken = t;
    room.inviteIssuedAt = Date.now();
    room.inviteExpiresAt = room.inviteIssuedAt + config.invite.ttlMs;
    room.invitesRevoked = false;
    this.byCode.set(c, room);
    this.byToken.set(t, room);
    return room;
  }

  revoke(room) {
    this._remove(room);
    room.inviteCode = null;
    room.inviteToken = null;
    room.invitesRevoked = true;
    return room;
  }

  unregister(room) {
    this._remove(room);
  }

  _valid(room) {
    return room && !room.destroyed && !room.invitesRevoked && room.maxPlayers > 1 &&
      (!room.inviteExpiresAt || room.inviteExpiresAt > Date.now());
  }

  resolveCode(code) {
    const c = typeof code === 'string' ? code.trim().toUpperCase() : '';
    if (!INVITE_CODE_RE.test(c)) return null;
    const room = this.byCode.get(c);
    return this._valid(room) ? room : null;
  }

  resolveToken(token) {
    const t = typeof token === 'string' ? token.trim() : '';
    if (!INVITE_TOKEN_RE.test(t)) return null;
    const room = this.byToken.get(t);
    return this._valid(room) ? room : null;
  }

  /** Rotate expired credentials of live rooms; returns the rooms that changed. */
  rotateExpired(now = Date.now()) {
    const rotated = [];
    for (const room of new Set(this.byToken.values())) {
      if (room.inviteExpiresAt && room.inviteExpiresAt <= now && !room.invitesRevoked) {
        this.issue(room);
        rotated.push(room);
      }
    }
    return rotated;
  }
}

export const inviteRegistry = new InviteRegistry();

/**
 * Accepts a raw code, token, or pasted link (?invite=<token> / ?join=<code|token>).
 * Returns {token, code}; exactly one is non-empty when the input is well-formed.
 */
export function parseInviteCredential(raw) {
  const s = typeof raw === 'string' ? raw.trim().slice(0, 512) : '';
  if (!s) return { token: '', code: '' };
  let val = s;
  const m = s.match(/[?&](invite|join)=([^&#\s]+)/);
  if (m) val = decodeURIComponentSafe(m[2]);
  if (INVITE_TOKEN_RE.test(val)) return { token: val, code: '' };
  const up = val.toUpperCase();
  if (INVITE_CODE_RE.test(up)) return { token: '', code: up };
  return { token: '', code: '' };
}

function decodeURIComponentSafe(s) {
  try { return decodeURIComponent(s); } catch { return ''; }
}
